        x = 0.08 + 0.23 * q + 0.04 * Math.sin(q * TAU * 1.7 + t * 0.45) * Math.sin(q * Math.PI);
        y = mix(0.085 * Math.sin(q * TAU * 1.2), -0.10 * Math.sin(q * Math.PI), bound)
          + 0.047 * Math.sin(q * 13 + t * 0.85) * Math.sin(q * Math.PI);
