    // including its responsive drawing area: large panels get a bolder tube.
    const pad = Math.max(14, w * 0.05), top = pad + 18;
    const strip = h - pad - Math.max(5, h * 0.016) - 4 - Math.max(16, h * 0.085);
    const bottom = strip - (w >= 400 ? 20 : Math.max(6, h * 0.02));
    const sc = Math.min((w - 2 * pad) / 40.8, (bottom - top) / 31);
    const tubeW = Math.max(2.2, 0.42 * sc);
    line(ctx, sample(0, 0.22, 55), th.ink, tubeW);
